def _passage_ranges(record: Mapping[str, Any]) -> list[tuple[int, int]]:
    body = str(record.get("body") or "")
    matches = list(PAGE_RE.finditer(body))
    if matches:
        starts = [0, *(match.start() for match in matches[1:])]
        ends = [*(match.start() for match in matches[1:]), len(body)]
        return [
            item
            for pair in zip(starts, ends, strict=True)
            if (item := _trimmed_range(body, *pair))
        ]
    full = _trimmed_range(body, 0, len(body))
    if full is None:
        return []
    ranges = [full]
    first_section = SECTION_RE.search(body)
    if len(body) >= LONG_RECORD_MIN_CHARS and first_section is not None:
        overview = _trimmed_range(body, 0, first_section.start())
        if overview is not None and overview != full:
            ranges.append(overview)
    for match in STRUCTURED_INTERPRETATION_RE.finditer(body):
        interpretation = _trimmed_range(body, *match.span())
        if interpretation is not None and interpretation not in ranges:
            ranges.append(interpretation)
    return ranges
